import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";

// Where attachment bytes live. The database only keeps the key, so moving to an object store
// (S3, MinIO) means writing another implementation of this interface and nothing else.
export interface AttachmentStorage {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  remove(key: string): Promise<void>;
}

// Keys are generated by the server (uuid + extension); this is the last line of defence against
// a key that would resolve outside the storage directory.
const SAFE_KEY = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

function assertSafeKey(key: string): void {
  if (!SAFE_KEY.test(key) || key.includes("..")) throw new Error("Invalid storage key");
}

export function createLocalDiskStorage(directory: string): AttachmentStorage {
  const root = path.resolve(directory);

  function fileOf(key: string): string {
    assertSafeKey(key);
    return path.join(root, key);
  }

  return {
    async put(key, data) {
      const file = fileOf(key);
      await mkdir(root, { recursive: true });
      await writeFile(file, data);
    },

    async get(key) {
      try {
        return await readFile(fileOf(key));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
        throw error;
      }
    },

    async remove(key) {
      await rm(fileOf(key), { force: true });
    },
  };
}
